using System.Globalization;
using System.Text;
using Rtok.Plugin.Sdk;

namespace Rtok.Agents.Hosts;

/// <summary>
/// The support table of <c>docs/agents.md</c>, rendered from the host table so the doc cannot
/// drift from the code (rtok <c>tests/agents_doc.rs</c>).
/// </summary>
public static class SupportMatrix
{
    /// <summary>The line before the generated table.</summary>
    public const string Start =
        "<!-- agents-table:start (generated by tests/Rtok.Agents.Hosts.Tests/SupportMatrixTests.cs) -->\n";

    /// <summary>The line after the generated table.</summary>
    public const string End = "<!-- agents-table:end -->\n";

    private static readonly Surface[] Surfaces =
    [
        Surface.Hook,
        Surface.Cli,
        Surface.Mcp,
        Surface.Proxy,
    ];

    /// <summary>
    /// One row per app: each module's support and the rtok surfaces the app reaches; then why
    /// each unsupported host has no installer, with the day and the docs it was checked against.
    /// </summary>
    public static string Table()
    {
        var text = new StringBuilder(
            "| Host | App | Kind | Hooks | MCP | Proxy | Plugin | rtok surfaces reached |\n"
                + "| --- | --- | --- | --- | --- | --- | --- | --- |\n"
        );
        foreach (var host in AgentHosts.All)
        {
            foreach (var v in host.Variants)
            {
                var modules = AgentHost.Modules.Select(m => Cell(host.SupportOf(m, v.Kind)));
                var reached = Surfaces
                    .Where(s => host.Reaches(v.Kind, s))
                    .Select(s => s.ToString().ToLowerInvariant())
                    .ToList();
                text.Append($"| `{host.Id}` | {v.Name} | {v.Kind.Label()} | ")
                    .AppendJoin(" | ", modules)
                    .Append(" | ")
                    .Append(reached.Count == 0 ? "—" : string.Join(", ", reached))
                    .Append(" |\n");
            }
        }
        foreach (var host in AgentHosts.Unsupported)
        {
            text.Append(
                $"| `{host.Id}` | {host.Name} | {host.Kind.Label()} | — | — | — | — | — |\n"
            );
        }
        text.Append("\nNot supported:\n\n");
        foreach (var host in AgentHosts.Unsupported)
        {
            text.Append(
                    $"- `{host.Id}`: {host.Reason}. Checked {host.Checked.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)} against "
                )
                .AppendJoin(", ", host.Sources.Select(s => $"<{s}>"))
                .Append(".\n");
        }
        return text.ToString();
    }

    private static string Cell(Support support) =>
        support.Level switch
        {
            SupportLevel.Yes => "yes",
            SupportLevel.Flag or SupportLevel.Offer => $"`{support.Note}`",
            _ => "—",
        };
}
